     1→// ============================================================================
     2→// FreeLang Transaction 모듈 - 스냅샷 기반 트랜잭션 관리
     3→// ============================================================================
     4→// 목표: schema.fl 테이블에 BEGIN/COMMIT/ROLLBACK 트랜잭션 지원
     5→// 원리:
     6→//   1. TxEntry: 각 변경 전 스냅샷 (이전 int/str/bool 값 저장)
     7→//   2. tx_insert: 삽입 후 row_id 기록 (롤백 시 소프트 삭제)
     8→//   3. tx_update: 이전 값 스냅샷 저장 후 업데이트
     9→//   4. tx_delete: 소프트 삭제 (롤백 시 복구)
    10→//   5. tx_rollback: TxEntry 역순으로 복구
    11→// 구조:
    12→//   - 상수 (상태, 연산 타입)
    13→//   - TxEntry, Transaction 구조체
    14→//   - 트랜잭션 CRUD
    15→//   - commit/rollback
    16→// ============================================================================
    17→
    18→module transaction {
    19→    // === 트랜잭션 상태 ===
    20→    const TX_ACTIVE:      i32 = 0;
    21→    const TX_COMMITTED:   i32 = 1;
    22→    const TX_ROLLED_BACK: i32 = 2;
    23→
    24→    // === 연산 타입 ===
    25→    const TX_OP_INSERT:      i32 = 1;
    26→    const TX_OP_UPDATE_INT:  i32 = 2;
    27→    const TX_OP_UPDATE_STR:  i32 = 3;
    28→    const TX_OP_UPDATE_BOOL: i32 = 4;
    29→    const TX_OP_DELETE:      i32 = 5;
    30→
    31→    // === 에러 코드 ===
    32→    const TX_OK:             i32 = 0;
    33→    const TX_ERR_NOT_ACTIVE: i32 = 40;
    34→    const TX_ERR_FULL:       i32 = 41;
    35→    const TX_ERR_NOTFOUND:   i32 = 42;
    36→
    37→    // === 제한값 ===
    38→    const MAX_TX_ENTRIES: i32 = 256;
    39→
    40→    // === 데이터 구조체 ===
    41→
    42→    // 트랜잭션 엔트리 (롤백용 스냅샷)
    43→    struct TxEntry {
    44→        op:       i32;     // TX_OP_*
    45→        row_id:   i64;
    46→        col_idx:  i32;     // UPDATE 시 컬럼 인덱스
    47→        old_int:  i64;     // UPDATE_INT 이전 값
    48→        old_str:  string;  // UPDATE_STR 이전 값
    49→        old_bool: bool;    // UPDATE_BOOL 이전 값
    50→    }
    51→
    52→    // 트랜잭션
    53→    struct Transaction {
    54→        id:          i64;
    55→        state:       i32;   // TX_ACTIVE / TX_COMMITTED / TX_ROLLED_BACK
    56→        entries:     [TxEntry];
    57→        entry_count: i32;
    58→    }
    59→
    60→    // 전역 트랜잭션 ID 카운터
    61→    let g_next_tx_id: i64 = 1;
    62→
    63→    // === 팩토리 함수 ===
    64→
    65→    func tx_begin() -> Transaction {
    66→        let tx_id = g_next_tx_id;
    67→        g_next_tx_id = g_next_tx_id + 1;
    68→        return Transaction{
    69→            id:          tx_id,
    70→            state:       TX_ACTIVE,
    71→            entries:     make([TxEntry], MAX_TX_ENTRIES),
    72→            entry_count: 0,
    73→        };
    74→    }
    75→
    76→    // === 트랜잭션 CRUD ===
    77→
    78→    // INSERT
    79→    func tx_insert(tx: *Transaction, t: *schema.Table, row: schema.RecordRow) -> (i64, i32) {
    80→        if tx.state != TX_ACTIVE {
    81→            return (0, TX_ERR_NOT_ACTIVE);
    82→        }
    83→        if tx.entry_count >= MAX_TX_ENTRIES {
    84→            return (0, TX_ERR_FULL);
    85→        }
    86→
    87→        let row_id, ok = t.table_insert(row);
    88→        if !ok {
    89→            return (0, TX_ERR_FULL);
    90→        }
    91→
    92→        tx.entries[tx.entry_count] = TxEntry{
    93→            op:       TX_OP_INSERT,
    94→            row_id:   row_id,
    95→            col_idx:  -1,
    96→            old_int:  0,
    97→            old_str:  "",
    98→            old_bool: false,
    99→        };
   100→        tx.entry_count = tx.entry_count + 1;
   101→
   102→        return (row_id, TX_OK);
   103→    }
   104→
   105→    // UPDATE INT (이전 값 스냅샷)
   106→    func tx_update_int(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: i64) -> i32 {
   107→        if tx.state != TX_ACTIVE {
   108→            return TX_ERR_NOT_ACTIVE;
   109→        }
   110→        if tx.entry_count >= MAX_TX_ENTRIES {
   111→            return TX_ERR_FULL;
   112→        }
   113→
   114→        // 이전 값 조회
   115→        let row, found = t.table_get(row_id);
   116→        if !found {
   117→            return TX_ERR_NOTFOUND;
   118→        }
   119→
   120→        // 타입 내 인덱스 계산
   121→        let type_idx = t.schema.col_type_idx(col_idx);
   122→        let old_val = row.int_vals[type_idx];
   123→
   124→        // 스냅샷 저장
   125→        tx.entries[tx.entry_count] = TxEntry{
   126→            op:       TX_OP_UPDATE_INT,
   127→            row_id:   row_id,
   128→            col_idx:  col_idx,
   129→            old_int:  old_val,
   130→            old_str:  "",
   131→            old_bool: false,
   132→        };
   133→        tx.entry_count = tx.entry_count + 1;
   134→
   135→        // 실제 업데이트
   136→        t.table_update_int(row_id, col_idx, new_val);
   137→        return TX_OK;
   138→    }
   139→
   140→    // UPDATE STR (이전 값 스냅샷)
   141→    func tx_update_str(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: string) -> i32 {
   142→        if tx.state != TX_ACTIVE {
   143→            return TX_ERR_NOT_ACTIVE;
   144→        }
   145→        if tx.entry_count >= MAX_TX_ENTRIES {
   146→            return TX_ERR_FULL;
   147→        }
   148→
   149→        let row, found = t.table_get(row_id);
   150→        if !found {
   151→            return TX_ERR_NOTFOUND;
   152→        }
   153→
   154→        let type_idx = t.schema.col_type_idx(col_idx);
   155→        let old_val = row.str_vals[type_idx];
   156→
   157→        tx.entries[tx.entry_count] = TxEntry{
   158→            op:       TX_OP_UPDATE_STR,
   159→            row_id:   row_id,
   160→            col_idx:  col_idx,
   161→            old_int:  0,
   162→            old_str:  old_val,
   163→            old_bool: false,
   164→        };
   165→        tx.entry_count = tx.entry_count + 1;
   166→
   167→        t.table_update_str(row_id, col_idx, new_val);
   168→        return TX_OK;
   169→    }
   170→
   171→    // UPDATE BOOL (이전 값 스냅샷)
   172→    func tx_update_bool(tx: *Transaction, t: *schema.Table, row_id: i64, col_idx: i32, new_val: bool) -> i32 {
   173→        if tx.state != TX_ACTIVE {
   174→            return TX_ERR_NOT_ACTIVE;
   175→        }
   176→        if tx.entry_count >= MAX_TX_ENTRIES {
   177→            return TX_ERR_FULL;
   178→        }
   179→
   180→        let row, found = t.table_get(row_id);
   181→        if !found {
   182→            return TX_ERR_NOTFOUND;
   183→        }
   184→
   185→        let type_idx = t.schema.col_type_idx(col_idx);
   186→        let old_val = row.bool_vals[type_idx];
   187→
   188→        tx.entries[tx.entry_count] = TxEntry{
   189→            op:       TX_OP_UPDATE_BOOL,
   190→            row_id:   row_id,
   191→            col_idx:  col_idx,
   192→            old_int:  0,
   193→            old_str:  "",
   194→            old_bool: old_val,
   195→        };
   196→        tx.entry_count = tx.entry_count + 1;
   197→
   198→        t.table_update_bool(row_id, col_idx, new_val);
   199→        return TX_OK;
   200→    }
   201→
   202→    // DELETE (소프트 삭제, 롤백 가능)
   203→    func tx_delete(tx: *Transaction, t: *schema.Table, row_id: i64) -> i32 {
   204→        if tx.state != TX_ACTIVE {
   205→            return TX_ERR_NOT_ACTIVE;
   206→        }
   207→        if tx.entry_count >= MAX_TX_ENTRIES {
   208→            return TX_ERR_FULL;
   209→        }
   210→
   211→        let _, found = t.table_get(row_id);
   212→        if !found {
   213→            return TX_ERR_NOTFOUND;
   214→        }
   215→
   216→        tx.entries[tx.entry_count] = TxEntry{
   217→            op:       TX_OP_DELETE,
   218→            row_id:   row_id,
   219→            col_idx:  -1,
   220→            old_int:  0,
   221→            old_str:  "",
   222→            old_bool: false,
   223→        };
   224→        tx.entry_count = tx.entry_count + 1;
   225→
   226→        t.table_delete(row_id);
   227→        return TX_OK;
   228→    }
   229→
   230→    // === COMMIT ===
   231→
   232→    func tx_commit(tx: *Transaction) -> bool {
   233→        if tx.state != TX_ACTIVE {
   234→            return false;
   235→        }
   236→        tx.state = TX_COMMITTED;
   237→        return true;
   238→    }
   239→
   240→    // === ROLLBACK ===
   241→
   242→    func tx_rollback(tx: *Transaction, t: *schema.Table) -> bool {
   243→        if tx.state != TX_ACTIVE {
   244→            return false;
   245→        }
   246→
   247→        // 역순으로 복구
   248→        let i = tx.entry_count - 1;
   249→        for i >= 0 {
   250→            let entry = tx.entries[i];
   251→
   252→            if entry.op == TX_OP_INSERT {
   253→                // 삽입 롤백: 소프트 삭제
   254→                t.table_delete(entry.row_id);
   255→
   256→            } else if entry.op == TX_OP_UPDATE_INT {
   257→                // UPDATE_INT 롤백: 이전 값 복원
   258→                t.table_update_int(entry.row_id, entry.col_idx, entry.old_int);
   259→
   260→            } else if entry.op == TX_OP_UPDATE_STR {
   261→                // UPDATE_STR 롤백: 이전 값 복원
   262→                t.table_update_str(entry.row_id, entry.col_idx, entry.old_str);
   263→
   264→            } else if entry.op == TX_OP_UPDATE_BOOL {
   265→                // UPDATE_BOOL 롤백: 이전 값 복원
   266→                t.table_update_bool(entry.row_id, entry.col_idx, entry.old_bool);
   267→
   268→            } else if entry.op == TX_OP_DELETE {
   269→                // DELETE 롤백: 소프트 삭제 해제 (삭제된 행 포함 탐색)
   270→                let j = 0;
   271→                for j = 0; j < t.row_count; j = j + 1 {
   272→                    if t.row_ids[j] == entry.row_id {
   273→                        t.deleted_flags[j] = false;
   274→                        break;
   275→                    }
   276→                }
   277→            }
   278→
   279→            i = i - 1;
   280→        }
   281→
   282→        tx.state = TX_ROLLED_BACK;
   283→        return true;
   284→    }
   285→
   286→    // === 상태 확인 ===
   287→
   288→    @inline
   289→    func tx_is_active(tx: Transaction) -> bool {
   290→        return tx.state == TX_ACTIVE;
   291→    }
   292→
   293→    @inline
   294→    func tx_is_committed(tx: Transaction) -> bool {
   295→        return tx.state == TX_COMMITTED;
   296→    }
   297→
   298→    @inline
   299→    func tx_is_rolled_back(tx: Transaction) -> bool {
   300→        return tx.state == TX_ROLLED_BACK;
   301→    }
   302→
   303→    // 트랜잭션 통계
   304→    func tx_stats(tx: Transaction) -> string {
   305→        let state_str = if tx.state == TX_ACTIVE {
   306→            "ACTIVE"
   307→        } else if tx.state == TX_COMMITTED {
   308→            "COMMITTED"
   309→        } else {
   310→            "ROLLED_BACK"
   311→        };
   312→        let msg = "[Tx " + i64_to_str(tx.id) + "] state=" + state_str +
   313→                  " entries=" + i32_to_str(tx.entry_count);
   314→        return msg;
   315→    }
   316→
   317→    // === 헬퍼 함수 ===
   318→
   319→    @inline
   320→    func i32_to_str(n: i32) -> string {
   321→        if n == 0 { return "0"; }
   322→        if n == 1 { return "1"; }
   323→        if n == 2 { return "2"; }
   324→        if n == 3 { return "3"; }
   325→        if n == 4 { return "4"; }
   326→        if n == 5 { return "5"; }
   327→        if n == 6 { return "6"; }
   328→        if n == 7 { return "7"; }
   329→        if n == 8 { return "8"; }
   330→        if n == 9 { return "9"; }
   331→        if n < 0 { return "-" + i32_to_str(-n); }
   332→        let d = n / 10;
   333→        let r = n % 10;
   334→        return i32_to_str(d) + i32_to_str(r);
   335→    }
   336→
   337→    @inline
   338→    func i64_to_str(n: i64) -> string {
   339→        if n == 0 { return "0"; }
   340→        if n < 0 { return "-" + i64_to_str(-n); }
   341→        return i32_to_str(i32(n));
   342→    }
   343→}
   344→
   345→// === 사용 시나리오 (주석) ===
   346→//
   347→// 기본 COMMIT:
   348→//   let tx = transaction.tx_begin();
