// ============================================================================
// FreeLang MVCC (Multi-Version Concurrency Control) 모듈
// ============================================================================
// 목표: 다중 트랜잭션 동시 실행을 위한 MVCC 구현
// 원리:
//   1. 각 행의 값에 대해 다양한 버전 유지 (행 변경 이력)
//   2. 각 트랜잭션은 시작 시점의 스냅샷에서만 데이터 읽음 (일관성)
//   3. 쓰기 충돌 감지: 같은 (row_id, col_idx)를 건드린 미커밋 트랜잭션 확인
//   4. 커밋: 모든 버전의 created_ts와 이전 버전의 deleted_ts 설정
//   5. 가비지 컬렉션: min_visible_ts보다 오래된 버전 삭제
//
// 구조:
//   - 상수 (MAX_VERSIONS=2048, MVCC_OK=0, 에러코드 70-74)
//   - VersionEntry 구조체 (행, 열, 값들, 타입, 타임스탐프, 커밋 상태)
//   - VersionStore 구조체 (버전 풀, 카운터, 다음 슬롯)
//   - 공개 API (init, next_ts, begin, read_*, write_*, commit, rollback, gc, stats)
//   - 내부 헬퍼 (가시성, 슬롯 할당, 충돌 감지)
// ============================================================================

module mvcc {
    // ========================================================================
    // 상수 정의
    // ========================================================================

    const MAX_VERSIONS: i32 = 2048;      // 최대 버전 개수
    const MAX_ACTIVE_TX: i32 = 64;       // 최대 활성 트랜잭션 개수
    const MVCC_TS_INF: i64 = -1;         // 무한 타임스탬프 (아직 삭제 안됨)

    // 연산 타입
    const VER_OP_INSERT: i32 = 1;
    const VER_OP_UPDATE: i32 = 2;
    const VER_OP_DELETE: i32 = 3;

    // 에러 코드
    const MVCC_OK:              i32 = 0;
    const MVCC_ERR_NOT_FOUND:   i32 = 70;
    const MVCC_ERR_CONFLICT:    i32 = 71;
    const MVCC_ERR_FULL:        i32 = 72;
    const MVCC_ERR_INVALID:     i32 = 73;

    // ========================================================================
    // 데이터 구조체
    // ========================================================================

    // VersionEntry: 단일 행의 단일 열에 대한 버전 정보
    struct VersionEntry {
        row_id:       i64;     // 행 ID
        col_idx:      i32;     // 열 인덱스 (-1: INSERT/DELETE)
        val_int:      i64;     // 정수 값
        val_str:      string;  // 문자열 값
        val_bool:     bool;    // 불린 값
        op_type:      i32;     // VER_OP_*
        created_ts:   i64;     // 생성 타임스탐프 (커밋 후 설정)
        deleted_ts:   i64;     // 삭제 타임스탐프 (다음 버전 커밋 시 설정, MVCC_TS_INF 초기값)
        tx_id:        i64;     // 트랜잭션 ID
        is_used:      bool;    // 슬롯 사용 여부
        is_committed: bool;    // 커밋됨 여부
    }

    // VersionStore: 모든 버전을 관리하는 저장소
    struct VersionStore {
        versions:     [VersionEntry];
        version_count: i32;
        next_slot:    i32;
    }

    // 전역 상태
    let g_global_ts: i64 = 1;          // 글로벌 타임스탬프 (계속 증가)
    let g_version_store: VersionStore = VersionStore{
        versions:      make([VersionEntry], 1),  // 임시, init()에서 올바르게 설정
        version_count: 0,
        next_slot:     0,
    };

    // ========================================================================
    // 공개 API - 초기화
    // ========================================================================

    func mvcc_init() -> i32 {
        g_version_store.versions = make([VersionEntry], MAX_VERSIONS);
        g_version_store.version_count = 0;
        g_version_store.next_slot = 0;
        return MVCC_OK;
    }

    // ========================================================================
    // 공개 API - 타임스탬프
    // ========================================================================

    // 다음 타임스탬프 획득 및 증가
    func mvcc_next_ts() -> i64 {
        let ret = g_global_ts;
        g_global_ts = g_global_ts + 1;
        return ret;
    }

    // ========================================================================
    // 공개 API - 트랜잭션 시작
    // ========================================================================

    // 트랜잭션 시작: 스냅샷 타임스탐프 반환
    func mvcc_begin(tx_id: i64) -> (i64, i32) {
        let snap_ts = mvcc_next_ts();
        return (snap_ts, MVCC_OK);
    }

    // ========================================================================
    // 공개 API - 읽기
    // ========================================================================

    // 정수 값 읽기
    func mvcc_read_int(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (i64, i32, i32) {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            let ver = vs.versions[i];
            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx {
                if is_version_visible(ver, snap_ts, tx_id) {
                    return (ver.val_int, i, MVCC_OK);
                }
            }
        }
        return (0, -1, MVCC_ERR_NOT_FOUND);
    }

    // 문자열 값 읽기
    func mvcc_read_str(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (string, i32, i32) {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            let ver = vs.versions[i];
            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx {
                if is_version_visible(ver, snap_ts, tx_id) {
                    return (ver.val_str, i, MVCC_OK);
