    func mvcc_read_bool(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (bool, i32, i32) {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
