    // 행이 주어진 스냅샷에서 보이는지 확인
    func mvcc_row_visible(vs: *VersionStore, row_id: i64, snap_ts: i64, tx_id: i64) -> bool {
        let i = 0;
        let insert_visible = false;
        let delete_visible = false;

        for i = 0; i < vs.version_count; i = i + 1 {
            let ver = vs.versions[i];
            if !ver.is_used {
                continue;
            }

            if ver.row_id == row_id && ver.col_idx == -1 {
                if ver.op_type == VER_OP_INSERT {
                    if is_version_visible(ver, snap_ts, tx_id) {
                        insert_visible = true;
                    }
                } else if ver.op_type == VER_OP_DELETE {
                    if is_version_visible(ver, snap_ts, tx_id) {
                        delete_visible = true;
                    }
                }
            }
        }

        return insert_visible && !delete_visible;
    }

