        if has_write_conflict(vs, row_id, col_idx, tx_id) {
            return (-1, MVCC_ERR_CONFLICT);
        }

        // 슬롯 할당
        let slot, allocated = vs_alloc_slot(vs);
        if !allocated {
            return (-1, MVCC_ERR_FULL);
        }

        // 버전 작성
        vs.versions[slot] = VersionEntry{
            row_id:       row_id,
            col_idx:      col_idx,
