    // 트랜잭션 커밋
    func mvcc_commit(vs: *VersionStore, tx_id: i64, commit_ts: i64) -> i32 {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            if vs.versions[i].is_used && vs.versions[i].tx_id == tx_id {
                // 현재 버전 커밋
                vs.versions[i].is_committed = true;
                vs.versions[i].created_ts = commit_ts;

                // 이전 버전의 deleted_ts 설정
                let j = 0;
                for j = 0; j < i; j = j + 1 {
                    let prev = vs.versions[j];
                    if prev.is_used && prev.row_id == vs.versions[i].row_id &&
                       prev.col_idx == vs.versions[i].col_idx && prev.is_committed &&
                       prev.deleted_ts == MVCC_TS_INF {
                        vs.versions[j].deleted_ts = commit_ts;
                    }
                }
            }
        }
        return MVCC_OK;
    }

    // 트랜잭션 롤백
    func mvcc_rollback(vs: *VersionStore, tx_id: i64) -> i32 {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            if vs.versions[i].is_used && vs.versions[i].tx_id == tx_id {
                vs.versions[i].is_used = false;
                vs.version_count = vs.version_count - 1;
            }
        }
        return MVCC_OK;
    }

