    // 오래된 버전 삭제 (min_visible_ts 이전 버전)
    func mvcc_gc(vs: *VersionStore, min_visible_ts: i64) -> i32 {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            let ver = vs.versions[i];
            if ver.is_used && ver.deleted_ts < min_visible_ts && ver.deleted_ts != MVCC_TS_INF {
                vs.versions[i].is_used = false;
                vs.version_count = vs.version_count - 1;
            }
        }
        return MVCC_OK;
    }

