    // 버전이 주어진 스냅샷에서 보이는지 확인
    @inline
    func is_version_visible(ver: VersionEntry, snap_ts: i64, tx_id: i64) -> bool {
        // 같은 트랜잭션이면 항상 보임
        if ver.tx_id == tx_id {
            return true;
        }

        // 커밋되지 않았으면 안 보임
        if !ver.is_committed {
            return false;
        }

        // 생성 타임스탐프가 스냅샷보다 크면 안 보임
        if ver.created_ts > snap_ts {
            return false;
        }

        // 삭제되지 않았으면 보임
        if ver.deleted_ts == MVCC_TS_INF {
            return true;
        }

        // 삭제 타임스탐프가 스냅샷보다 크면 보임 (아직 삭제 전)
        if ver.deleted_ts > snap_ts {
            return true;
        }

        return false;
    }

    // 빈 슬롯 할당 (원형 버퍼)
    func vs_alloc_slot(vs: *VersionStore) -> (i32, bool) {
        let attempt = 0;
        for attempt = 0; attempt < MAX_VERSIONS; attempt = attempt + 1 {
            let slot = vs.next_slot;
            vs.next_slot = (vs.next_slot + 1) % MAX_VERSIONS;

            if !vs.versions[slot].is_used {
                return (slot, true);
            }
        }
        return (-1, false);
    }

    // 쓰기 충돌 감지
    func has_write_conflict(vs: *VersionStore, row_id: i64, col_idx: i32, tx_id: i64) -> bool {
        let i = 0;
        for i = 0; i < vs.version_count; i = i + 1 {
            let ver = vs.versions[i];
            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx &&
               ver.tx_id != tx_id && !ver.is_committed {
                return true;
            }
        }
        return false;
    }

